import {APP_BASE_HREF, DOCUMENT} from '@angular/common';
import {
    Component,
    Inject,
    InjectFlags,
    Injector,
    OnInit,
    Self,
    ViewEncapsulation,
} from '@angular/core';
import {NavigationEnd, Router} from '@angular/router';
import {changeDetection} from '@demo/emulate/change-detection';
import {LOCAL_STORAGE} from '@ng-web-apis/common';
import {TUI_DOC_PAGE_LOADED} from '@taiga-ui/addon-doc';
import {TUI_IS_E2E, TuiDestroyService, TuiResizeService} from '@taiga-ui/cdk';
import {Metrika} from 'ng-yandex-metrika';
import {Observable} from 'rxjs';
import {distinctUntilChanged, filter, map, takeUntil} from 'rxjs/operators';

import {environment} from '../../environments/environment';
import {AbstractDemoComponent, DEMO_PAGE_LOADED_PROVIDER} from './abstract.app';
import {
    TUI_SELECTED_VERSION_META,
    TUI_VERSION_MANAGER_PROVIDERS,
} from './version-manager/version-manager.providers';
import {TuiVersionMeta} from './version-manager/versions.constants';

@Component({
    selector: 'app',
    templateUrl: './app.template.html',
    styleUrls: ['./app.style.less'],
    providers: [
        TuiResizeService,
        TuiDestroyService,
        DEMO_PAGE_LOADED_PROVIDER,
        TUI_VERSION_MANAGER_PROVIDERS,
    ],
    encapsulation: ViewEncapsulation.None,
    changeDetection,
})
export class AppComponent extends AbstractDemoComponent implements OnInit {
    readonly isLanding$ = this.router.events.pipe(
        map(() => this.router.routerState.snapshot.url === '/'),
        distinctUntilChanged(),
    );

    constructor(
        @Inject(TUI_IS_E2E) isE2E: boolean,
        @Inject(TUI_DOC_PAGE_LOADED) pageLoaded$: Observable<boolean>,
        @Inject(TUI_SELECTED_VERSION_META) selectedVersion: TuiVersionMeta | null,
        @Inject(Router) protected readonly router: Router,
        @Inject(LOCAL_STORAGE) protected readonly storage: Storage,
        @Self() @Inject(TuiDestroyService) private readonly destroy$: Observable<void>,
        @Inject(Injector) private readonly injector: Injector,
        @Inject(DOCUMENT) private readonly doc: Document,
        @Inject(APP_BASE_HREF) private readonly appBaseHref: string,
    ) {
        super(isE2E, pageLoaded$, selectedVersion);
    }

    override async ngOnInit(): Promise<void> {
        await super.ngOnInit();
        this.enableYandexMetrika();
        this.setBaseHrefIfNotPresent();
    }

    private enableYandexMetrika(): void {
        if (ngDevMode && (!environment.production || this.isE2E)) {
            console.info('Yandex.Metrika disabled for non-production mode.');

            return;
        }

        try {
            const metrika = this.injector.get(Metrika, null, InjectFlags.Optional);

            this.router.events
                .pipe(
                    filter(
                        (event): event is NavigationEnd => event instanceof NavigationEnd,
                    ),
                    takeUntil(this.destroy$),
                )
                .subscribe(event => {
                    // eslint-disable-next-line
                    metrika?.hit(event.urlAfterRedirects, {referer: event.url});
                });
        } catch {
            ngDevMode && console.error('You forgot to import MetrikaModule!');
        }
    }

    /**
     * @description:
     * By default, on webcontainer.io will not be provided base[href] in index.html,
     * we use fallback for correct processing of routing
     */
    private setBaseHrefIfNotPresent(): void {
        if (this.doc.getElementsByTagName('base')?.[0]?.href) {
            return;
        }

        const base = this.doc.createElement('base');

        base.href = this.appBaseHref;
        this.doc.getElementsByTagName('head')?.[0]?.appendChild(base);
    }
}

import {
    APP_BASE_HREF,
    DOCUMENT,
    isPlatformBrowser,
    LocationStrategy,
    PathLocationStrategy,
} from '@angular/common';
import {inject, PLATFORM_ID, Provider} from '@angular/core';
import {Title} from '@angular/platform-browser';
import {ANIMATION_MODULE_TYPE} from '@angular/platform-browser/animations';
import {UrlTree} from '@angular/router';
import {SESSION_STORAGE} from '@ng-web-apis/common';
import {
    TUI_DOC_CODE_EDITOR,
    TUI_DOC_DEFAULT_TABS,
    TUI_DOC_EXAMPLE_CONTENT_PROCESSOR,
    TUI_DOC_LOGO,
    TUI_DOC_PAGES,
    TUI_DOC_SCROLL_BEHAVIOR,
    TUI_DOC_SEE_ALSO,
    TUI_DOC_SOURCE_CODE,
    TUI_DOC_TITLE,
    TUI_DOC_URL_STATE_HANDLER,
    tuiDocExampleOptionsProvider,
    TuiDocSourceCodePathOptions,
} from '@taiga-ui/addon-doc';
import {
    TUI_DIALOG_CLOSES_ON_BACK,
    TUI_ENSURE_BASE_HREF,
    TUI_IS_E2E,
    TUI_IS_PLAYWRIGHT,
    TUI_TAKE_ONLY_TRUSTED_EVENTS,
    tuiAssert,
} from '@taiga-ui/cdk';
import {
    TUI_ANIMATIONS_DURATION,
    TUI_DROPDOWN_HOVER_DEFAULT_OPTIONS,
    TUI_DROPDOWN_HOVER_OPTIONS,
    TUI_HINT_DEFAULT_OPTIONS,
    TUI_HINT_OPTIONS,
    TUI_REDUCED_MOTION,
    TUI_SANITIZER,
} from '@taiga-ui/core';
import {TuiLanguageName, tuiLanguageSwitcher} from '@taiga-ui/i18n';
import {NgDompurifySanitizer} from '@tinkoff/ng-dompurify';
import {HIGHLIGHT_OPTIONS} from 'ngx-highlightjs';
import {of} from 'rxjs';

import {PROMPT_PROVIDER} from '../customization/dialogs/examples/1/prompt/prompt.service';
import {SEE_ALSO_GROUPS} from './app.const';
import {TUI_DEFAULT_TABS} from './app.tabs';
import {LOGO_CONTENT} from './logo/logo.component';
import {pages} from './pages';
import {TuiStackblitzService} from './stackblitz/stackblitz.service';
import {exampleContentProcessor} from './utils';

export const APP_PROVIDERS: Provider[] = [
    Title,
    PROMPT_PROVIDER,
    {
        provide: APP_BASE_HREF,
        // @note: By default, on webcontainer.io will not be provided APP_BASE_HREF, we use fallback
        useFactory: () => inject(DOCUMENT).querySelector(`base`)?.href || `/`,
    },
    {
        provide: TUI_IS_PLAYWRIGHT,
        useFactory: () => Boolean(inject(SESSION_STORAGE).getItem(`playwright`)),
    },
    {
        provide: HIGHLIGHT_OPTIONS,
        useFactory: () => {
            const isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

            return {
                coreLibraryLoader: async () => import(`highlight.js/lib/core`),
                lineNumbersLoader: async () =>
                    // SSR ReferenceError: window is not defined
                    isBrowser ? import(`highlightjs-line-numbers.js`) : Promise.resolve(),
                languages: {
                    typescript: async () =>
                        import(`highlight.js/lib/languages/typescript`),
                    less: async () => import(`highlight.js/lib/languages/less`),
                    xml: async () => import(`highlight.js/lib/languages/xml`),
                },
            };
        },
    },
    {
        provide: TUI_SANITIZER,
        useClass: NgDompurifySanitizer,
    },
    {
        provide: TUI_DOC_SOURCE_CODE,
        useValue: ({type, path, header, package: pkg}: TuiDocSourceCodePathOptions) => {
            const link = `https://github.com/taiga-family/taiga-ui/tree/main/projects`;

            if (!pkg) {
                return null;
            }

            ngDevMode &&
                tuiAssert.assert(
                    !(type && path),
                    `Don't use "type" and "path" input params together in tui-doc-page`,
                );

            if (type) {
                return `${link}/${pkg.toLowerCase()}/${type.toLowerCase()}/${(
                    header[0].toLowerCase() + header.slice(1)
                ).replace(/[A-Z]/g, m => `-${m.toLowerCase()}`)}`;
            }

            return `${link}/${path}`;
        },
    },
    {
        provide: LocationStrategy,
        useClass: PathLocationStrategy,
    },
    {
        provide: TUI_DOC_TITLE,
        useValue: `Taiga UI: `,
    },
    {
        provide: TUI_DOC_PAGES,
        useValue: pages,
    },
    {
        provide: TUI_DOC_SEE_ALSO,
        useValue: SEE_ALSO_GROUPS,
    },
    {
        provide: TUI_DOC_DEFAULT_TABS,
        useValue: TUI_DEFAULT_TABS,
    },
    {
        provide: TUI_DOC_LOGO,
        useValue: LOGO_CONTENT,
    },
    {
        provide: TUI_DOC_CODE_EDITOR,
        useClass: TuiStackblitzService,
    },
    {
        provide: TUI_DOC_EXAMPLE_CONTENT_PROCESSOR,
        useValue: exampleContentProcessor,
    },
    {
        provide: ANIMATION_MODULE_TYPE,
        useFactory: () =>
            inject(TUI_IS_E2E) || inject(TUI_REDUCED_MOTION)
                ? `NoopAnimations`
                : `BrowserAnimations`,
    },
    {
        provide: TUI_ANIMATIONS_DURATION,
        useFactory: () => (inject(TUI_IS_E2E) || inject(TUI_REDUCED_MOTION) ? 0 : 300),
    },
    {
        provide: TUI_HINT_OPTIONS,
        useFactory: () =>
            inject(TUI_IS_E2E)
                ? {...TUI_HINT_DEFAULT_OPTIONS, showDelay: 0, hideDelay: 0}
                : TUI_HINT_DEFAULT_OPTIONS,
    },
    {
        provide: TUI_DROPDOWN_HOVER_OPTIONS,
        useFactory: () =>
            inject(TUI_IS_E2E)
                ? {...TUI_DROPDOWN_HOVER_DEFAULT_OPTIONS, showDelay: 0, hideDelay: 0}
                : TUI_DROPDOWN_HOVER_DEFAULT_OPTIONS,
    },
    {
        provide: TUI_DOC_SCROLL_BEHAVIOR,
        useFactory: () =>
            inject(TUI_IS_E2E) || inject(TUI_REDUCED_MOTION) ? `auto` : `smooth`, // https://github.com/cypress-io/cypress/issues/4640
    },
    {
        provide: TUI_TAKE_ONLY_TRUSTED_EVENTS,
        useFactory: () => !inject(TUI_IS_E2E),
    },
    {
        provide: TUI_DIALOG_CLOSES_ON_BACK,
        // TODO: change it back after solving https://github.com/taiga-family/taiga-ui/issues/3270
        // useFactory: () => of(!tuiIsInsideIframe(inject(WINDOW))), // for cypress tests
        useFactory: () => of(inject(TUI_IS_E2E)),
    },
    {
        provide: TUI_DOC_URL_STATE_HANDLER,
        deps: [TUI_ENSURE_BASE_HREF],
        useFactory: (baseHref: string) => (tree: UrlTree) =>
            String(tree).replace(baseHref, ``),
    },
    tuiDocExampleOptionsProvider({fullsize: false}),
    tuiLanguageSwitcher(
        async (language: TuiLanguageName): Promise<unknown> =>
            import(
                /* webpackMode: "lazy" */
                /* webpackChunkName: "i18n-lazy-" */
                `dist/i18n/esm2015/languages/${language}`
            ),
    ),
];

